            _uiState.value = repository.reconcilePaymentStatus(paymentAttemptId)
        }
    }
}
```
عند موت العملية وعودة المستخدم، يُعاد بناء الـ ViewModel ويقرأ المعرف من `SavedStateHandle` ويستعلم عن حالة الدفع من السيرفر بدلاً من تكرار الخصم.

AND-08.worked_example_ar:
في شاشة المحادثة الفورية، يتم فتح اتصال WebSocket وإغلاقه عند تدمير الشاشة نهائياً عبر `onCleared()`:
```kotlin
class ChatViewModel(
    private val chatSocket: ChatSocketManager,
    private val repository: MessageRepository
) : ViewModel() {
    init {
        chatSocket.connect()
    }

    fun send(text: String) {
        viewModelScope.launch { repository.sendMessage(text) }
    }

    override fun onCleared() {
        super.onCleared()
        // تُستدعى فقط عند مغادرة الشاشة نهائياً وليس عند التدوير
        chatSocket.disconnect()
    }
}
```
عند تدوير الشاشة 10 مرات، لا تُستدعى `onCleared()` ويظل الاتصال مستمراً، وتُستدعى مرة واحدة فقط عند الضغط على زر الرجوع لإنهاء المحادثة.

