معالجة صلاحية الكاميرا باستخدام Activity Result API وحالات الرفض:
```kotlin
class CameraActivity : AppCompatActivity() {
    private val requestCameraLauncher = registerForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        if (isGranted) {
            openCamera()
        } else if (!ActivityCompat.shouldShowRequestPermissionRationale(this, Manifest.permission.CAMERA)) {
            // رفض دائم: توجيه لإعدادات النظام
            showSettingsDialog()
        } else {
            // رفض مؤقت: توضيح سبب الاحتياج
            showRationaleDialog()
        }
    }

    private fun showSettingsDialog() {
        AlertDialog.Builder(this)
            .setTitle("مطلوب صلاحية الكاميرا")
            .setMessage("تم تعطيل الصلاحية بشكل دائم، يرجى تفعيلها من إعدادات التطبيق للمتابعة.")
            .setPositiveButton("فتح الإعدادات") { _, _ ->
                val intent = Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {
                    data = Uri.fromParts("package", packageName, null)
                }
                startActivity(intent)
            }
            .setNegativeButton("إلغاء", null)
            .show()
    }
}
```

