التنقل الحديث Type-Safe Compose Navigation مع دعم الـ Deep Links:
```kotlin
@Serializable
data object CatalogRoute

@Serializable
data class ProductRoute(val id: String)

@Composable
fun NavigationGraph(navController: NavHostController) {
    NavHost(navController = navController, startDestination = CatalogRoute) {
        composable<CatalogRoute> {
            CatalogScreen(onProductSelect = { id ->
                navController.navigate(ProductRoute(id = id))
            })
        }
        composable<ProductRoute>(
            deepLinks = listOf(
                navDeepLink<ProductRoute>(basePath = "https://store.example.com/products")
            )
        ) { backStackEntry ->
            val route: ProductRoute = backStackEntry.toRoute()
            ProductScreen(productId = route.id)
        }
    }
}
```
